fn compare(actual:Option<&Tensor>,expected:&Option<Golden>,label:&str) {
 let Some(e)=expected else {assert!(actual.is_none(),"{label}: expected absent");return;};let a=actual.expect(label);
 assert_eq!(a.shape(),e.shape,"{label} shape");assert_eq!(a.strides(),e.stride,"{label} strides");
 assert_eq!(a.dtype(),if e.wide{DType::F64}else{DType::F32},"{label} dtype");assert_eq!(a.requires_grad(),e.live,"{label} live");assert_eq!(a.is_leaf(),e.leaf,"{label} leaf");assert_eq!(a.is_structural_zero(),e.marker,"{label} marker");
 for (i,(&a,&b)) in a.to_vec_f64().iter().zip(e.values).enumerate() {assert!((a.is_nan()&&b.is_nan()) || a==b || a.is_finite()&&b.is_finite()&&(a-b).abs()<=2e-6+2e-6*b.abs(),"{label}[{i}] {a} != {b}");}
}
#[test]
fn actual_torch_cumulative_physical_scalar_width_one_ties_empty_dtypes_and_modes() {
 for (index,c) in CASES.iter().enumerate() {
  let x=Tensor::from_vec(c.data.iter().map(|v|*v as f32).collect(),c.shape).unwrap().requires_grad_(true).unwrap();
  let mut ss=vec![2];ss.extend_from_slice(c.shape);
  let seed=if c.seedwide {Tensor::from_vec_f64(c.seed.to_vec(),&ss).unwrap()} else {Tensor::from_vec(c.seed.iter().map(|v|*v as f32).collect(),&ss).unwrap()}.requires_grad_(true).unwrap();
  let tangent=with_grad_enabled(c.enabled,||->Result<Tensor>{
   let level=DualLevel::functional_batched(&[&x],&[&seed],2)?;
   let y=if c.kind=="cumprod" {x.cumprod_dtype(c.axis,if c.outwide{Some(DType::F64)}else{None})?} else {
    let input=if c.outwide{x.to_dtype_autograd(DType::F64,false)?}else{x.clone()};
    if c.kind=="cummax"{input.cummax(c.axis)?.0}else{input.cummin(c.axis)?.0}
   };
   let tangent=level.batched_tangent(&y)?.expect("cumulative direction");drop(level);Ok(tangent)
  }).unwrap_or_else(|e|panic!("case{index} {} {:?}: {e:?}",c.kind,c.shape));
  compare(Some(&tangent),&c.direction,&format!("case{index} direction"));
  let gradients=if tangent.requires_grad(){let total=tangent.sum();let one=if total.dtype()==DType::F64{Tensor::from_vec_f64(vec![1.],&[]).unwrap()}else{Tensor::scalar(1.)};Tensor::vjp_many_wrt_optional(&[&total],&[&x,&seed],&[&one],false).unwrap()}else{vec![None,None]};
  for (i,(actual,expected)) in gradients.iter().zip(&c.gradients).enumerate(){compare(actual.as_ref(),expected,&format!("case{index} gradient{i}"));}
  assert!(x.grad().is_none()&&seed.grad().is_none());assert!(is_grad_enabled()&&!is_active());
 }
 println!("{} actual Torch physical cumulative controls",CASES.len());
}

#[test]
fn rounded_division_broadcasts_output_zero_but_rounding_owns_physical_seed_zero() {
 for transposed in [false,true] {for kind in 0..4 {
  let mut x=Tensor::from_vec(vec![0.3,0.7,1.3,1.7,2.3,2.7],&[2,3]).unwrap();if transposed{x=x.transpose(0,1).unwrap();}
  let mut entries=vec![0.;36];for i in 0..6{entries[i*6+i]=1.;}let mut ss=vec![6];ss.extend_from_slice(x.shape());let seed=Tensor::from_vec(entries,&ss).unwrap();
  let level=DualLevel::functional_batched(&[&x],&[&seed],6).unwrap();
  let y=match kind {0=>x.div_rounding(&Tensor::scalar(1.2),ferro_core::ops_ext::div_rounding::DivisionRounding::Floor).unwrap(),1=>x.div_rounding(&Tensor::scalar(1.2),ferro_core::ops_ext::div_rounding::DivisionRounding::Trunc).unwrap(),2=>x.floor().unwrap(),_=>x.round().unwrap()};
  let tangent=level.batched_tangent(&y).unwrap().unwrap();drop(level);
  let mut shape=y.shape().to_vec();shape.extend_from_slice(x.shape());let jac=tangent.permute(&[1,2,0]).unwrap().view(&shape).unwrap();
  let expected=match (kind<2,transposed){(true,false)=>vec![3,1,0,0],(true,true)=>vec![1,3,0,0],(false,false)=>vec![3,1,18,6],(false,true)=>vec![1,3,12,6]};
  assert_eq!(jac.strides(),expected,"kind{kind} transposed{transposed}");assert!(!jac.requires_grad()&&!jac.is_structural_zero());assert!(jac.to_vec().iter().all(|v|v.to_bits()==0));
  assert!(jac.mul(&Tensor::scalar(f32::INFINITY)).unwrap().to_vec().iter().all(|v|v.is_nan()));
 }}
}

#[test]
fn scalar_extrema_preserves_saved_direction_index_versions_and_level_cleanup() {
 for maximum in [false,true] {for change_index in [false,true] {
  let x=Tensor::scalar(0.7);let seed=Tensor::from_vec(vec![0.3,-0.4],&[2]).unwrap().requires_grad_(true).unwrap();
  let level=DualLevel::functional_batched(&[&x],&[&seed],2).unwrap();let (value,index)=if maximum{x.cummax(0).unwrap()}else{x.cummin(0).unwrap()};let tangent=level.batched_tangent(&value).unwrap().unwrap();drop(level);
  if change_index{index.copy_from(&Tensor::from_vec_i64(vec![0],&[]).unwrap()).unwrap();}else{seed.detach().copy_from(&Tensor::from_vec(vec![0.8,0.9],&[2]).unwrap()).unwrap();}
  assert!(tangent.sum().grad_wrt(&[&seed],false).is_err());assert!(seed.grad().is_none());
 }}
 let x=Tensor::from_vec(vec![0.2,0.7],&[2]).unwrap();let seed=Tensor::ones(&[2,2]);let level=DualLevel::functional_batched(&[&x],&[&seed],2).unwrap();let y=x.floor_divide(&Tensor::scalar(1.2)).unwrap();assert!(level.batched_tangent(&y).is_err());drop(level);
 assert!(is_grad_enabled()&&!is_active());let level=DualLevel::functional_batched(&[&x],&[&seed],2).unwrap();assert_eq!(level.batched_tangent(&x.sum()).unwrap().unwrap().to_vec(),vec![2.,2.]);drop(level);
}
